70	fn parse_nonzero_port(value: &str) -> Result<u16, String> {
71	    let port = value
72	        .parse::<u16>()
73	        .map_err(|error| format!("invalid port `{value}`: {error}"))?;
74	    if port == 0 {
75	        return Err("port must be greater than zero".to_string());
76	    }
77	    Ok(port)
