97	fn validate_response_buffer_size(response_buffer_size: isize) -> PyResult<ResponseBufferMode> {
98	    let capacity = usize::try_from(response_buffer_size)
99	        .map_err(|_| PyValueError::new_err("response_buffer_size must be non-negative"))?;
100	
101	    if capacity == 0 {
102	        return Ok(ResponseBufferMode::Rendezvous);
103	    }
104	
105	    if capacity > MAX_RESPONSE_BUFFER_SIZE {
106	        return Err(PyValueError::new_err(format!(
107	            "response_buffer_size must not exceed {MAX_RESPONSE_BUFFER_SIZE}"
108	        )));
109	    }
110	
111	    Ok(ResponseBufferMode::Buffered(capacity))
112	}
