457	#[cfg(feature = "select-service")]
458	pub(crate) fn run_select_service_cli<I, T>(
459	    args: I,
460	    policy_registry: WorkerSelectionPolicyRegistry,
461	) -> anyhow::Result<()>
462	where
463	    I: IntoIterator<Item = T>,
464	    T: Into<OsString>,
465	{
466	    let cli = SelectServiceCli::try_parse_from(
467	        std::iter::once(OsString::from("python -m dynamo.select_service"))
468	            .chain(args.into_iter().map(Into::into)),
469	    )?;
470	
471	    init_standalone_logging();
472	
473	    let mut kv_router_config =
474	        try_kv_router_config_from_dynamo_env().map_err(anyhow::Error::msg)?;
475	    if let Some(assume_kv_reuse) = cli.router_assume_kv_reuse_override() {
476	        kv_router_config.router_assume_kv_reuse = assume_kv_reuse;
477	    }
478	    if let Some(algorithm) = cli.router_tracking_hash {
479	        kv_router_config.router_tracking_hash = algorithm;
480	    }
481	    if let Some(key_file) = cli.router_tracking_key_file {
482	        kv_router_config.router_tracking_key_file = Some(key_file);
483	    }
484	    if let Some(key_id) = cli.router_tracking_key_id {
485	        kv_router_config.router_tracking_key_id = Some(key_id);
486	    }
487	    warn_for_unserved_worker_selection_policies(&kv_router_config, &[WorkerType::Aggregated])?;
488	    let config = SelectionServiceConfig {
489	        port: cli.port,
490	        threads: cli.threads,
491	        indexer_peers: cli.indexer_peers,
492	        replica_sync_port: cli.replica_sync_port,
493	        replica_sync_peers: cli.replica_sync_peers,
494	        kv_router_config,
495	        selection_cache: selection_cache_config_from_overrides(
496	            cli.selection_cache_ttl_secs,
497	            cli.selection_cache_max_entries,
498	            cli.selection_cache_max_bytes,
499	        ),
500	    };
501	    let builder = config.service_builder(WorkerType::Aggregated, policy_registry);
502	    let rt = tokio::runtime::Runtime::new()?;
503	    let service = rt.block_on(builder.build())?;
504	    rt.block_on(selection::run_server(config.port, service))
505	}
