507	/// Map a [`SelectionError`] to a Python exception: invalid input becomes a
508	/// `ValueError`, anything else a `SelectionServiceError` carrying `kind` and
509	/// `status_code`.
510	#[cfg(feature = "select-service")]
511	fn selection_to_pyerr(err: SelectionError) -> PyErr {
512	    if let SelectionError::BadRequest(message) = &err {
513	        return PyValueError::new_err(message.clone());
514	    }
515	    let message = err.to_string();
516	    let kind = err.kind();
517	    let status_code = err.status_code();
518	    Python::with_gil(|py| {
519	        let pyerr = crate::errors::SelectionServiceError::new_err(message);
520	        let value = pyerr.value(py);
521	        let _ = value.setattr("kind", kind);
522	        let _ = value.setattr("status_code", status_code);
523	        pyerr
524	    })
525	}
