527	/// Build a [`RsSelectionCacheConfig`] from optional overrides, falling back to
528	/// the service default for each field left unset. Shared by the Python
529	/// `SelectionCacheConfig` and the `dynamo.select_service` CLI.
530	#[cfg(feature = "select-service")]
531	fn selection_cache_config_from_overrides(
532	    ttl_secs: Option<f64>,
533	    max_entries: Option<usize>,
534	    max_bytes: Option<usize>,
535	) -> RsSelectionCacheConfig {
536	    let mut config = RsSelectionCacheConfig::default();
537	    if let Some(ttl_secs) = ttl_secs {
538	        config.ttl = std::time::Duration::from_secs_f64(ttl_secs);
539	    }
540	    if let Some(max_entries) = max_entries {
541	        config.max_entries = max_entries;
542	    }
543	    if let Some(max_bytes) = max_bytes {
544	        config.max_bytes = max_bytes;
545	    }
546	    config
547	}
