579	impl SelectionService {
580	    /// Create a selection service. `indexer_threads` sizes the KV indexer pool.
581	    #[new]
582	    #[pyo3(signature = (*, indexer_threads = 4, indexer_peers = None, replica_sync_port = None, replica_sync_peers = None, selection_cache = None))]
