584	        py: Python<'_>,
585	        indexer_threads: usize,
586	        indexer_peers: Option<Vec<String>>,
587	        replica_sync_port: Option<u16>,
588	        replica_sync_peers: Option<Vec<String>>,
589	        selection_cache: Option<SelectionCacheConfig>,
590	    ) -> PyResult<Self> {
591	        let replica_sync_peers = replica_sync_peers.unwrap_or_default();
592	        if replica_sync_port.is_none() && !replica_sync_peers.is_empty() {
593	            return Err(PyValueError::new_err(
594	                "replica_sync_peers requires replica_sync_port",
595	            ));
596	        }
597	        let kv_router_config =
598	            try_kv_router_config_from_dynamo_env().map_err(PyValueError::new_err)?;
599	        warn_for_unserved_worker_selection_policies(&kv_router_config, &[WorkerType::Aggregated])
600	            .map_err(to_pyerr)?;
601	        let mut builder = SelectionServiceBuilder::new(
602	            kv_router_config,
603	            WorkerType::Aggregated,
604	            crate::linked_worker_selection_policy_registry(),
605	        )
606	        .indexer_threads(indexer_threads)
607	        .indexer_peers(indexer_peers.unwrap_or_default())
608	        .selection_cache(selection_cache.unwrap_or_default().inner);
609	        if let Some(port) = replica_sync_port {
610	            builder = builder.replica_sync(port, replica_sync_peers);
611	        }
612	        let inner = py
613	            .allow_threads(|| pyo3_async_runtimes::tokio::get_runtime().block_on(builder.build()))
614	            .map_err(to_pyerr)?;
615	        Ok(Self {
616	            inner: Arc::new(inner),
617	        })
618	    }
