1557	impl RadixTree {
1558	    fn handle_request(
1559	        radix_tree: &mut dynamo_kv_router::indexer::RadixTree,
1560	        request: RadixTreeRequest,
1561	    ) {
1562	        match request {
1563	            RadixTreeRequest::FindMatches {
1564	                local_block_hashes,
1565	                early_exit,
1566	                response_tx,
1567	            } => {
1568	                let result = radix_tree.find_matches(local_block_hashes, early_exit);
1569	                let _ = response_tx.send(result);
1570	            }
1571	            RadixTreeRequest::ApplyEvent {
1572	                worker_id,
1573	                kv_cache_event_bytes,
1574	                response_tx,
1575	            } => {
1576	                let result = match serde_json::from_slice::<KvCacheEvent>(&kv_cache_event_bytes) {
1577	                    Ok(kv_cache_event) => {
1578	                        let router_event = RouterEvent::new(worker_id, kv_cache_event);
1579	                        match radix_tree.apply_event(router_event) {
1580	                            Ok(_) => Ok(()),
1581	                            Err(e) => Err(PyErr::new::<pyo3::exceptions::PyRuntimeError, _>(
1582	                                format!("Failed to apply event: {}", e),
1583	                            )),
1584	                        }
1585	                    }
1586	                    Err(e) => Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
1587	                        "Failed to deserialize KvCacheEvent: {}",
1588	                        e
1589	                    ))),
1590	                };
1591	                let _ = response_tx.send(result);
1592	            }
1593	            RadixTreeRequest::RemoveWorker {
1594	                worker_id,
1595	                response_tx,
1596	            } => {
1597	                radix_tree.remove_worker(worker_id);
1598	                let _ = response_tx.send(());
1599	            }
1600	            RadixTreeRequest::ClearAllBlocks {
1601	                worker_id,
1602	                response_tx,
1603	            } => {
1604	                radix_tree.clear_all_blocks(worker_id);
1605	                let _ = response_tx.send(());
1606	            }
1607	            RadixTreeRequest::DumpTreeAsEvents { response_tx } => {
1608	                let events = radix_tree.dump_tree_as_events();
1609	                let _ = response_tx.send(events);
1610	            }
1611	            RadixTreeRequest::Shutdown => {
1612	                // This is handled in the main loop
1613	            }
1614	        }
1615	    }
1616	}
