1880	impl KvRouter {
1881	    /// Helper method to process a request and create a Python async generator
1882	    fn process_request_to_stream<'p>(
1883	        py: Python<'p>,
1884	        inner: Arc<RsRoutingHost>,
1885	        request: llm_rs::protocols::common::preprocessor::PreprocessedRequest,
1886	        tracker: Option<Arc<RequestTracker>>,
1887	        response_buffer_size: usize,
1888	    ) -> PyResult<Bound<'p, PyAny>> {
1889	        pyo3_async_runtimes::tokio::future_into_py(py, async move {
1890	            let single_in = SingleIn::new(request);
1891	            let stream = inner.generate(single_in).await.map_err(to_pyerr)?;
1892	            let (tx, rx) =
1893	                tokio::sync::mpsc::channel::<RsAnnotated<PyObject>>(response_buffer_size);
1894	
1895	            tokio::spawn(async move {
1896	                let mut stream = stream;
1897	                let mut first_item = true;
1898	                let mut first_token_gauges_observed = false;
1899	
1900	                while let Some(mut response) = stream.next().await {
1901	                    if first_item {
1902	                        first_item = false;
1903	                        if let (Some(tracker), Some(data)) = (&tracker, &mut response.data) {
1904	                            inject_worker_id_from_tracker(data, tracker);
1905	                        }
1906	                    }
1907	
1908	                    if !first_token_gauges_observed {
1909	                        let has_tokens = response
1910	                            .data
1911	                            .as_ref()
1912	                            .map(|d| !d.token_ids.is_empty())
1913	                            .unwrap_or(false);
1914	                        if has_tokens {
1915	                            if let Some(ref tracker) = tracker {
1916	                                tracker.observe_first_token_gauges();
1917	                            }
1918	                            first_token_gauges_observed = true;
1919	                        }
1920	                    }
1921	
1922	                    // On the terminal chunk, finalize timing and attach it for the frontend.
1923	                    if let (Some(tracker), Some(data)) = (&tracker, &mut response.data)
1924	                        && data.finish_reason.is_some()
1925	                    {
1926	                        tracker.record_finish();
1927	                        inject_timing_from_tracker(data, tracker);
1928	                    }
1929	
1930	                    let response = response.map_data(|data| {
1931	                        Python::with_gil(|py| {
1932	                            pythonize(py, &data)
1933	                                .map(|obj| obj.unbind())
1934	                                .map_err(|error| error.to_string())
1935	                        })
1936	                    });
1937	                    let is_error = response.is_error();
1938	
1939	                    if tx.send(response).await.is_err() {
1940	                        break;
1941	                    }
1942	                    if is_error {
1943	                        break;
1944	                    }
1945	                }
1946	
1947	                if let Some(ref tracker) = tracker {
1948	                    tracker.observe_finish_gauges();
1949	                }
1950	            });
1951	
1952	            Ok(crate::AsyncResponseStream::new(rx, false))
1953	        })
1954	    }
1955	
1956	    fn dispatch_request_to_stream<'p>(
1957	        py: Python<'p>,
1958	        inner: Arc<RsRoutingHost>,
1959	        request: llm_rs::protocols::common::preprocessor::PreprocessedRequest,
1960	        tracker: Option<Arc<RequestTracker>>,
1961	        response_buffer_mode: ResponseBufferMode,
1962	    ) -> PyResult<Bound<'p, PyAny>> {
1963	        match response_buffer_mode {
1964	            ResponseBufferMode::Rendezvous => {
1965	                demand_driven::process_request_to_stream(py, inner, request, tracker)
1966	            }
1967	            ResponseBufferMode::Buffered(capacity) => {
1968	                Self::process_request_to_stream(py, inner, request, tracker, capacity)
1969	            }
1970	        }
1971	    }
1972	}
