#[cfg(any(feature = "slot-tracker", feature = "select-service"))]
fn parse_nonzero_port(value: &str) -> Result<u16, String> {
    let port = value
        .parse::<u16>()
        .map_err(|error| format!("invalid port `{value}`: {error}"))?;
    if port == 0 {
        return Err("port must be greater than zero".to_string());
    }
    Ok(port)
}

